<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class PracticePartnerController extends Controller{
private function access($token){$a=DB::table('practice_partner_access')->where(['token'=>$token,'active'=>1])->where(function($q){$q->whereNull('expires_at')->orWhere('expires_at','>',now());})->first();abort_if(!$a,403,'Ссылка недействительна');DB::table('practice_partner_access')->where('id',$a->id)->update(['last_used_at'=>now(),'updated_at'=>now()]);return $a;}
public function index($token){$a=$this->access($token);$org=DB::table('practice_organizations')->find($a->practice_organization_id);$rows=DB::table('practice_placements as p')->join('students as s','s.id','=','p.student_id')->where('p.practice_organization_id',$org->id)->whereIn('p.status',['planned','active'])->select('p.id','p.practice_type','p.starts_on','p.ends_on','p.organization_characteristic','p.attestation_grade','s.last_name','s.first_name','s.middle_name')->orderBy('s.last_name')->get();$diary=DB::table('practice_diary_entries as d')->join('practice_placements as p','p.id','=','d.practice_placement_id')->join('students as s','s.id','=','p.student_id')->where('p.practice_organization_id',$org->id)->where('d.partner_status','pending')->select('d.*','s.last_name','s.first_name')->orderBy('d.work_date')->get();return view('practice-office.partner',compact('token','org','rows','diary'));}
public function save(Request $r,$token,$placement){$a=$this->access($token);$p=DB::table('practice_placements')->where(['id'=>$placement,'practice_organization_id'=>$a->practice_organization_id])->first();abort_if(!$p,404);$d=$r->validate(['organization_characteristic'=>'required|string|max:20000','attestation_grade'=>'required|string|max:50']);DB::table('practice_placements')->where('id',$placement)->update($d+['updated_at'=>now()]);DB::table('practice_document_checks')->updateOrInsert(['practice_placement_id'=>$placement,'document_type'=>'characteristic'],['status'=>'submitted','checked_at'=>now(),'updated_at'=>now(),'created_at'=>now()]);return back()->with('success','Характеристика сохранена.');}
public function diary(Request $r,$token,$entry){$a=$this->access($token);$d=DB::table('practice_diary_entries as d')->join('practice_placements as p','p.id','=','d.practice_placement_id')->where('d.id',$entry)->where('p.practice_organization_id',$a->practice_organization_id)->select('d.*')->first();abort_if(!$d,404);$v=$r->validate(['status'=>'required|in:confirmed,rejected','partner_comment'=>'nullable|string|max:2000']);DB::table('practice_diary_entries')->where('id',$entry)->update(['partner_status'=>$v['status'],'partner_comment'=>$v['partner_comment']??null,'partner_confirmed_at'=>now(),'updated_at'=>now()]);return back()->with('success','Запись дневника обработана.');}
}